79	/// Drive `bench` against `cfg` and return
80	/// `(histogram, outer, inner, duration_s)`.
81	///
82	/// After a fixed warmup, `inner` is auto-sized so apparatus framing
83	/// doesn't dominate (skipped when `cfg.inner_override` is set). The
84	/// outer loop runs either for `cfg.outer_override` iterations or
85	/// until `cfg.target_seconds` elapses.
86	pub fn run_adaptive<B: Bench>(bench: &mut B, cfg: &RunCfg) -> (Histogram<u64>, u64, u64, f64) {
87	    for _ in 0..WARMUP {
88	        black_box(bench.step());
89	    }
90	
91	    let step_cost_ns = estimate_step_cost(bench);
92	    let framing_ns = cfg.overhead.framing_per_sample_ns.max(1.0);
93	    let inner = cfg
94	        .inner_override
95	        .unwrap_or_else(|| pick_inner(step_cost_ns, framing_ns));
96	
97	    let clocks = ClockPair::now();
98	    let (hist, outer, duration_s) = match cfg.outer_override {
99	        Some(outer) => {
