101	            (hist, outer, duration_s)
102	        }
103	        None => {
104	            let (hist, duration_s) = run_timed(bench, cfg.target_seconds, inner);
105	            let outer = hist.len();
106	            (hist, outer, duration_s)
107	        }
108	    };
109	    warn_invalid(bench.name(), &hist, &clocks);
110	    (hist, outer, inner, duration_s)
111	}
112	
113	fn estimate_step_cost<B: Bench>(bench: &mut B) -> f64 {
114	    let mut samples: Vec<f64> = (0..ESTIMATE_SAMPLES)
115	        .map(|_| {
116	            let start = minstant::Instant::now();
117	            for _ in 0..ESTIMATE_STEPS {
118	                black_box(bench.step());
119	            }
120	            let total = start.elapsed().as_nanos() as u64;
121	            total as f64 / ESTIMATE_STEPS as f64
122	        })
